create table if not exists planets (name text primary key, radius_km int, moons int);
insert into planets values
  ('Mercury', 2440, 0), ('Venus', 6052, 0), ('Earth', 6371, 1),
  ('Mars', 3390, 2), ('Pluto', 1188, 5)
on conflict do nothing;
select * from planets order by radius_km desc;

// sql`` runs on the same Postgres; interpolations become parameters
const minMoons = 1
await sql`select name, moons from planets where moons >= ${minMoons} order by moons desc`

create table if not exists notes (id integer primary key, body text, created text default current_timestamp);
insert into notes (body) values ('first note'), ('second note');
select * from notes order by id desc limit 5;

select region, sum(amount) as total, count(*) as orders
from read_csv('sales.csv')
group by region
order by total desc;
